using System;
using System.IO;
using Furycube.G9.Oled;

internal static class OledRuntimeStatusTests {
    // Independent Python CCITT-FALSE fixtures, not generated by this decoder.
    const string Valid = "IoRHUwMBAgOADAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAADcn";
    const string Invalid = "IoRHUwMAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAOyn";
    const string Busy = "IoRHUwMCAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAKPc";
    static int count;
    static DateTimeOffset Now = new DateTimeOffset(2026,11,9,1,0,0,TimeSpan.Zero);
    static void Check(bool value, string name) { if (!value) throw new Exception("FAIL " + name); count++; }
    static void Reject(Action action, string name) {
        try { action(); } catch (FormatException) { count++; return; } catch (InvalidOperationException) { count++; return; }
        catch (NotSupportedException) { count++; return; } catch (ArgumentException) { count++; return; }
        throw new Exception("FAIL accepted " + name);
    }
    static byte[] Change(byte[] frame,int position,byte value,bool crc=true) {
        byte[] result=(byte[])frame.Clone(); result[position]=value;
        if(crc) { ushort check=OledProtocol.Crc16CcittFalse(result,0,130); result[130]=(byte)check; result[131]=(byte)(check>>8); }
        return result;
    }
    sealed class Fake : IOledTransport, IOledRuntimeStatusTransport {
        internal int Versions, StatusReads, Writes;
        internal ushort Pid=0x2148;
        internal byte Marker=(byte)'3';
        internal byte[] Status=Convert.FromBase64String(Valid);
        public ushort VendorId {get{return 0x1D57;}} public ushort ProductId {get{return Pid;}}
        public byte[] ReadFirmwareVersion(){Versions++;return new byte[]{11,8,1,1,8,(byte)'O',(byte)'L',Marker};}
        public byte[] ReadRuntimeStatus(){StatusReads++;return (byte[])Status.Clone();}
        public void SendFeature(byte[] packet){OledProtocol.DecodeWritePage(packet);Writes++;}
    }
    sealed class Session : IOledDeviceSession, IOledRuntimeStatusDeviceSession {
        internal int Versions,StatusReads,Writes; internal ushort Pid=0x2148; internal byte Marker=(byte)'3';
        public ushort VendorId {get{return 0x1D57;}} public ushort ProductId {get{return Pid;}}
        public byte[] ReadOledFirmware(){Versions++;return new byte[]{11,8,1,1,8,(byte)'O',(byte)'L',Marker};}
        public byte[] ReadOledRuntimeStatus(){StatusReads++;return Convert.FromBase64String(Valid);}
        public void SendOledFeature(byte[] report){Writes++;}
    }
    static int Main(){try{
        byte[] valid=Convert.FromBase64String(Valid),invalid=Convert.FromBase64String(Invalid),busy=Convert.FromBase64String(Busy);
        Check(valid.Length==132&&invalid.Length==132&&busy.Length==132,"independent fixtures are132bytes");
        Check(valid[130]==0x37&&valid[131]==0x27,"independent valid CRC little-endian2737");
        var status=OledRuntimeStatusCodec.Decode(valid,Now);
        Check(status.IsValid&&!status.IsBusy&&status.ProfileId==2&&status.Stage==3&&status.ConfiguredDpi==3200,"atomic configured DPI fields");
        Check(status.ReceivedAtUtc==Now&&status.IsFresh(Now)&&status.IsFresh(Now.AddSeconds(1)),"fresh inclusive one-second lifetime");
        Check(!status.IsFresh(Now.AddMilliseconds(1001))&&!status.IsFresh(Now.AddMilliseconds(-1)),"stale/future values unavailable");
        Check(status.IsFresh(Now.AddMilliseconds(500),TimeSpan.FromMilliseconds(500))&&!status.IsFresh(Now.AddMilliseconds(501),TimeSpan.FromMilliseconds(500)),"caller can shorten freshness");
        Reject(delegate{status.IsFresh(Now,TimeSpan.FromMilliseconds(1001));},"caller cannot extend freshness beyond1s");
        Reject(delegate{status.IsFresh(Now,TimeSpan.FromMilliseconds(-1));},"negative freshness");
        Check(OledRuntimeStatusCodec.Decode(valid,Now.ToOffset(TimeSpan.FromHours(3))).ReceivedAtUtc.Offset==TimeSpan.Zero,"timestamp normalized UTC");
        var absent=OledRuntimeStatusCodec.Decode(invalid,Now); var waiting=OledRuntimeStatusCodec.Decode(busy,Now);
        Check(!absent.IsValid&&!absent.IsBusy&&absent.ProfileId==null&&absent.Stage==null&&absent.ConfiguredDpi==null,"invalid frame cannot expose fields");
        Check(!waiting.IsValid&&waiting.IsBusy&&waiting.ProfileId==null&&waiting.Stage==null&&waiting.ConfiguredDpi==null,"busy frame cannot expose fields");
        valid[6]=5;Check(status.ProfileId==2,"decoded object does not retain mutable input");valid=Convert.FromBase64String(Valid);
        Reject(delegate{OledRuntimeStatusCodec.Decode(null,Now);},"null");
        Reject(delegate{OledRuntimeStatusCodec.Decode(new byte[131],Now);},"short frame");
        Reject(delegate{OledRuntimeStatusCodec.Decode(new byte[133],Now);},"long frame");
        foreach(int at in new[]{0,1,2,3,4}) {int index=at;Reject(delegate{OledRuntimeStatusCodec.Decode(Change(valid,index,0),Now);},"header field"+at);}
        Reject(delegate{OledRuntimeStatusCodec.Decode(Change(valid,5,3),Now);},"unknown status");
        foreach(byte profile in new byte[]{0,6,255}){byte value=profile;Reject(delegate{OledRuntimeStatusCodec.Decode(Change(valid,6,value),Now);},"profile bounds"+profile);}
        foreach(byte stage in new byte[]{0,9,255}){byte value=stage;Reject(delegate{OledRuntimeStatusCodec.Decode(Change(valid,7,value),Now);},"stage bounds"+stage);}
        byte[] zeroDpi=Change(Change(valid,8,0),9,0);Reject(delegate{OledRuntimeStatusCodec.Decode(zeroDpi,Now);},"zero valid DPI");
        foreach(byte[] source in new[]{invalid,busy})for(int at=6;at<10;at++){byte[] dirty=Change(source,at,1);Reject(delegate{OledRuntimeStatusCodec.Decode(dirty,Now);},"invalid/busy stale value"+at);}
        for(int at=10;at<130;at++){byte[] dirty=Change(valid,at,1);Reject(delegate{OledRuntimeStatusCodec.Decode(dirty,Now);},"reserved padding"+at);}
        Reject(delegate{OledRuntimeStatusCodec.Decode(Change(valid,130,0,false),Now);},"CRC corruption");
        Check(BitConverter.ToString(OledRuntimeStatusCodec.BuildReadRequest())=="A0-22-84-00-00-00-00-00","selector-zero request shape");
        var fake=new Fake();var sender=new OledSender(fake,delegate(int delay){});
        Reject(delegate{sender.ReadRuntimeStatusFrame();},"status before discovery");Check(fake.Versions==0&&fake.StatusReads==0&&fake.Writes==0,"no implicit traffic");
        Check(sender.Discover().SupportsRuntimeStatus&&sender.Capabilities.Extension=="OL3","OL3 capabilities");
        Check(OledRuntimeStatusCodec.Decode(sender.ReadRuntimeStatusFrame(),Now).ConfiguredDpi==3200&&fake.StatusReads==1&&fake.Versions==1,"OL3 read uses existing discovery");
        sender.WriteFrame(new byte[480]);Check(fake.Writes==4,"OL3 retains unchanged v2 page protocol");
        var old=new Fake{Marker=(byte)'2'};var oldSender=new OledSender(old);Check(!oldSender.Discover().SupportsRuntimeStatus,"OL2 lacks status");
        Reject(delegate{oldSender.ReadRuntimeStatusFrame();},"OL2 status disabled");Check(old.StatusReads==0&&old.Writes==0,"OL2 never receives status GET");
        fake.Status=Change(fake.Status,130,0,false);Reject(delegate{sender.ReadRuntimeStatusFrame();},"malformed status invalidates sender");Check(sender.Capabilities==null,"failed status requires new discovery");
        var nativeSession=new Session();var adapter=new NativeOledTransport(nativeSession);
        Reject(delegate{adapter.ReadRuntimeStatus();},"native status before discovery");Check(nativeSession.StatusReads==0,"native guard precedes session call");
        adapter.ReadFirmwareVersion();adapter.ReadRuntimeStatus();Check(nativeSession.Versions==1&&nativeSession.StatusReads==1,"same native session read");
        nativeSession.Pid=0xFA60;Reject(delegate{adapter.ReadRuntimeStatus();},"changed identity before status");Check(nativeSession.StatusReads==1,"identity mismatch never reaches session status");
        var nativeOld=new Session{Marker=(byte)'2'};var oldAdapter=new NativeOledTransport(nativeOld);oldAdapter.ReadFirmwareVersion();Reject(delegate{oldAdapter.ReadRuntimeStatus();},"native OL2 status guard");Check(nativeOld.StatusReads==0,"native OL2 has no status call");
        Console.WriteLine("PASS "+count+" OL3 status codec, freshness, same-session and OL2 negative fixtures; fake transport only.");return 0;
    }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
